researchCss:
/* docsync:prune — to-document.mjs keeps only the rules a slide uses. */
/* Research talk: white 1280x720 canvas, absolute layout, semantic colour tokens. Example template for motion decks.
   Colour meaning for this deck (keep one role per hue on every slide):
   teal  = the local / physical side of the system
   blue  = the remote / network / preparation side
   amber = the thing the paper moves, updates or contributes
   red   = problems and limits only
   To re-theme, override the tokens in :root. Single-slide rules go in slides/SLIDE_ID.css, scoped by #SLIDE_ID. */
:root{
  --bg:#fff;--paper:#fff;
  --ink:#14233F;--text:#2B3649;--muted:#5B687C;--faint:#8D99AB;--line:#D5DDE8;--soft:#F3F6FA;
  --teal:#0D8682;--teal-soft:#E1F2F0;--teal-ink:#075E5B;
  --blue:#2C69D6;--blue-soft:#E6EEFC;--blue-ink:#1C4CA6;
  --amber:#E1970F;--amber-soft:#FDF1DA;--amber-ink:#8A5700;
  --red:#BF3F38;--red-soft:#FBE7E5;--red-ink:#962F29;
  --f-head:"Space Grotesk","Segoe UI",system-ui,Arial,sans-serif;
  --f-body:"Inter","Segoe UI",system-ui,Arial,sans-serif;
  --f-mono:"JetBrains Mono",ui-monospace,Consolas,"Courier New",monospace;
}
/* Absolute-layout canvas on top of presentation-base.css (which adds padding, flex and a dark theme). */
.slide.research{display:block;padding:0;background:var(--paper);color:var(--text);font:22px/1.35 var(--f-body);-webkit-font-smoothing:antialiased;--m-hl:var(--amber);--m-hl-soft:var(--amber-soft);--m-on:var(--teal);--m-on-soft:var(--teal-soft);--m-on-ink:var(--teal-ink);--m-wire:var(--faint)}
.research *,.research *::before,.research *::after{box-sizing:border-box}
.research p{margin:0}
.research em{font-family:inherit;color:inherit}
.slide.research[hidden]{display:none}
.abs{position:absolute}

/* header */
.kick{position:absolute;left:64px;top:34px;margin:0;display:flex;align-items:center;gap:14px;font:600 14px/1 var(--f-body);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.ev{display:inline-flex;align-items:center;gap:7px;padding:5px 10px;border-radius:99px;border:1.5px solid var(--line);font:600 14px/1 var(--f-body);letter-spacing:.04em;color:var(--muted)}
.ev::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--ink)}
.ev.measured::before{background:var(--teal)}.ev.concept::before{background:var(--blue)}.ev.illus::before{background:var(--amber)}.ev.future::before{background:transparent;border:1.5px dashed var(--muted)}
.research>h2{position:absolute;left:64px;top:58px;margin:0;width:1150px;font:700 38px/1.15 var(--f-head);color:var(--ink);letter-spacing:-.01em;text-wrap:balance}

/* text */
.lead{font-size:23px;color:var(--text)}
.lead b,.k{color:var(--ink);font-weight:700}
.small{font-size:17px;line-height:1.35}
.cap{font-size:14px;line-height:1.3;color:var(--muted)}
.label{font:600 14px/1.2 var(--f-body);letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.mono{font-family:var(--f-mono)}
.head{font:700 24px/1.15 var(--f-head);color:var(--ink)}
ul.clean,ol.clean{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}
.clean>li{display:flex;gap:12px;align-items:flex-start}
.dot{flex:none;width:9px;height:9px;margin-top:9px;border-radius:50%;background:var(--c,var(--ink))}

/* surfaces */
.box{border-radius:12px;padding:16px 18px;background:var(--soft)}
.node{position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;text-align:center;border-radius:12px;padding:10px 12px;font-size:18px;line-height:1.25;background:var(--paper)}
.node.row{flex-direction:row;gap:10px}
.node b{color:var(--ink);font-size:19px}
.chip{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:7px;border:1.5px solid var(--line);background:var(--paper);font-size:16px;white-space:nowrap}
.tag{display:inline-block;padding:4px 8px;border-radius:6px;background:var(--soft);font:600 14px/1 var(--f-body);letter-spacing:.05em;text-transform:uppercase;color:var(--muted)}
.tag.amber{background:var(--amber-soft);color:var(--amber-ink)}.tag.teal{background:var(--teal-soft);color:var(--teal-ink)}.tag.blue{background:var(--blue-soft);color:var(--blue-ink)}.tag.fut{background:transparent;border:1.5px dashed var(--faint)}
.badge{flex:none;display:inline-grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--c,var(--ink));color:#fff;font:700 15px/1 var(--f-head)}
.slide figure{margin:0}
.slide figure img{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:6px;background:#fff}
.slide figcaption{margin-top:5px;font-size:14px;color:var(--muted)}
.fig-ph{display:grid;place-items:center;gap:6px;min-height:160px;border:2px dashed var(--line);border-radius:8px;background:var(--soft);color:var(--muted);font-size:15px;text-align:center;padding:16px}
table.t{border-collapse:collapse;width:100%;font-size:19px}
table.t th{padding:8px 12px;border:0;border-bottom:2px solid var(--ink);font:600 14px/1.2 var(--f-body);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);text-align:left}
table.t td{padding:11px 12px;border:0;border-bottom:1px solid var(--line);vertical-align:top}
table.t .n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
table.t td:first-child{color:var(--ink);font-weight:600}

.cover-venue{font:600 14px/1.3 var(--f-body);letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.slide h1.cover-title{margin:18px 0 0;font:700 76px/1 var(--f-head);color:var(--ink);letter-spacing:-.02em;text-wrap:balance}
.cover-sub{margin:14px 0 0!important;font:500 30px/1.2 var(--f-head);color:var(--ink);text-wrap:balance}
.cover-hook{margin:22px 0 0!important;max-width:560px;font-size:22px;font-style:italic;color:var(--amber-ink)}
.cover-meta{margin-top:40px;display:flex;flex-direction:column;gap:8px;font-size:18px}

.dv-eyebrow{font:600 18px/1 var(--f-body);letter-spacing:.12em;text-transform:uppercase;color:var(--teal-ink)}
.slide h1.dv-title{margin:16px 0 0;font:700 64px/1.05 var(--f-head);color:var(--ink);letter-spacing:-.02em;text-wrap:balance}
.dv-list{list-style:none;margin:40px 0 0;padding:0;display:flex;flex-direction:column;gap:14px}
.dv-list li{display:flex;align-items:center;gap:16px;font:500 26px/1.2 var(--f-body);color:var(--ink)}
.dv-list .badge{width:36px;height:36px;font-size:16px;background:var(--teal)}
.dv-map{display:flex;align-items:center;gap:10px;font:600 14px/1 var(--f-mono)}
.dv-map .label{margin-right:8px}
.dv-map .d{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;border:1.5px solid var(--line);color:var(--faint)}
.dv-map .d.on{background:var(--ink);border-color:var(--ink);color:#fff}

.agenda{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}
.agenda li{display:grid;grid-template-columns:30px 1fr auto;align-items:center;gap:16px;padding:6px 0;border-bottom:1px solid var(--line);font-size:24px;font-weight:500;color:var(--ink)}
.agenda em{font:400 14px/1 var(--f-mono);font-style:normal;color:var(--muted)}

.lane{position:absolute;display:flex;align-items:center}
.lane .lbl{flex:none;width:190px;padding-right:14px;font:700 17px/1.2 var(--f-body);color:var(--ink)}
:where(.lane) .st{flex:none;width:190px;height:66px;display:grid;place-items:center;padding:6px 10px;border-radius:10px;border:2px solid var(--line);background:var(--paper);text-align:center;font-size:18px;line-height:1.2}
.lane .ar{flex:none;position:relative;width:46px;height:16px;color:var(--faint)}
.lane .ar::before{content:"";position:absolute;left:6px;right:12px;top:7px;height:2.4px;border-radius:2px;background:currentColor}
.lane .ar::after{content:"";position:absolute;right:6px;top:2px;border-left:10px solid currentColor;border-top:6px solid transparent;border-bottom:6px solid transparent}

.state{position:absolute;width:150px;height:62px;display:grid;place-items:center;border-radius:31px;border:2px solid var(--line);background:var(--paper);font:600 19px/1 var(--f-body);color:var(--ink)}

.term-row{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.term{display:grid;grid-template-columns:44px 1fr;gap:14px;align-items:start;min-height:196px;padding:16px 18px;border-radius:12px;background:var(--soft)}
.term b{display:block;font:700 24px/1.1 var(--f-head);color:var(--ink)}
.term em{display:block;margin:6px 0 8px;font:600 14px/1 var(--f-body);font-style:normal;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.term span:not(.ic){display:block;font-size:16px;line-height:1.4;color:var(--text)}

.grp{display:flex;flex-direction:column;gap:8px;height:346px;padding:18px 20px;border-radius:14px;background:var(--soft);font-size:17px;line-height:1.38}
.grp-h{display:flex;gap:12px;align-items:center;margin-bottom:6px}
.grp-h b{font:700 21px/1.15 var(--f-head);color:var(--ink)}
.grp-x{margin-top:auto;display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border:2px solid var(--red);border-radius:10px;background:var(--paper);font-size:16px;line-height:1.35}
.grp-x b{color:var(--red)}
.spectrum{height:6px;border-radius:3px;background:linear-gradient(90deg,var(--red),var(--amber) 50%,var(--teal))}
.spectrum::after{content:"";position:absolute;right:-12px;top:-6px;border-left:14px solid var(--teal);border-top:9px solid transparent;border-bottom:9px solid transparent}
.spectrum-l{font:600 14px/1 var(--f-body);letter-spacing:.04em;text-transform:uppercase}

.nlist{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:9px}
.nlist li{display:grid;grid-template-columns:34px 30px 1fr;gap:14px;align-items:start;padding:9px 16px;border-left:4px solid var(--c,var(--amber));border-radius:0 10px 10px 0;background:var(--soft)}
.nlist.plain li{padding:8px 0;border-left:0;border-bottom:1px solid var(--line);border-radius:0;background:none}
.nlist .badge{background:var(--c,var(--amber))}
.nlist b{display:block;font:700 21px/1.25 var(--f-head);color:var(--ink)}
.nlist span:not(.badge):not(.ic){display:block;margin-top:3px;font-size:16px;line-height:1.35;color:var(--muted)}

.band{position:absolute;left:64px;width:600px;height:118px;display:grid;grid-template-columns:110px 1fr;align-items:center;padding:0 18px;border-radius:12px}
.band .bl{font:700 24px/1 var(--f-head)}
.band .br{font-size:19px;font-weight:600;color:var(--ink)}
.band .bc{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}

.wn{position:absolute;width:200px;min-height:84px;display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border:2px solid var(--teal);border-radius:12px;background:var(--paper);font-size:16px;line-height:1.25;color:var(--ink)}
.wn .badge{width:26px;height:26px;font-size:14px}

.segs{display:flex;height:84px;border:2px solid var(--ink);border-radius:10px;overflow:hidden}
.seg{display:flex;flex-direction:column;justify-content:center;padding:0 12px;border-right:1.5px solid var(--line);font-size:15px;line-height:1.25}
.seg b{font-size:16px}
.seg.hatch{background:repeating-linear-gradient(135deg,#E3E7EE 0 8px,#F3F5F9 8px 16px);color:var(--muted)}

.op{display:block;padding:9px 10px;border-radius:8px;border:1.5px solid var(--line);background:#fff;font:500 15px/1 var(--f-mono);color:var(--muted);transition:background .35s,border-color .35s,color .35s}
:root:not(.mo-js) .op:not(.off),.op.in{background:var(--teal-soft);border-color:var(--teal);color:var(--teal-ink);font-weight:600}
.op.off{border-style:dashed;color:var(--faint)}

.stat{font:700 44px/1 var(--f-head);color:var(--ink);font-variant-numeric:tabular-nums}
.stat small{font-size:22px}

.verdict{list-style:none;margin:18px 0 0;padding:0;display:flex;flex-direction:column;gap:16px;font-size:20px}
.verdict li{display:flex;gap:12px;align-items:flex-start}

.rows-h,.rows{display:grid;grid-template-columns:var(--c1,250px) 1fr 1fr 1fr;gap:20px}
.rows-h{padding:0 14px 8px;border-bottom:2px solid var(--ink);font:600 14px/1.2 var(--f-body);letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.rows{align-items:start;min-height:108px;padding:14px;border-radius:12px;background:var(--soft);font-size:15.5px;line-height:1.35;color:var(--text)}
.rows .rt{display:flex;gap:12px;align-items:center}
.rows .rt b{font:700 20px/1.15 var(--f-head);color:var(--ink)}

.usteps{display:flex;flex-direction:column;gap:8px}
.ustep{display:flex;gap:12px;align-items:flex-start;padding:9px 12px;border:1.5px solid var(--line);border-radius:10px;background:var(--paper);font-size:15px;line-height:1.3}
.ustep .badge{width:26px;height:26px;margin-top:1px;font-size:14px}
.ustep b{display:block;margin-bottom:2px;font-size:16.5px;color:var(--ink)}

.plot{position:absolute;border-left:1.6px solid var(--ink);border-bottom:1.6px solid var(--ink)}
.plot .zone{position:absolute;top:0;bottom:0}
.plot .hl{position:absolute;left:0;right:0;border-top:1.6px dashed var(--faint)}
.plot .vl{position:absolute;top:0;bottom:0;border-left:2px solid var(--c,var(--ink))}
.plot .vl.dashed{border-left-style:dashed;border-left-width:1.4px}
.plot .yl{position:absolute;right:calc(100% + 8px);transform:translateY(-50%);font-size:14px;color:var(--muted);white-space:nowrap}
.plot .ev-l{position:absolute;bottom:calc(100% + 4px);font-size:14px;font-weight:600;white-space:nowrap}

.code{margin:0;padding:12px;border-radius:8px;background:var(--soft);font:14.5px/1.5 var(--f-mono);color:var(--ink);white-space:pre}

.refs{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:18px;font:21px/1.4 "Times New Roman",Times,serif;color:var(--ink)}
.refs li{display:grid;grid-template-columns:48px 1fr;gap:6px}
.refs .url{overflow-wrap:anywhere;color:var(--blue-ink)}

/* Colour utilities come last so they override component defaults at equal specificity. */
.b-teal{background:var(--teal-soft)}.b-blue{background:var(--blue-soft)}.b-amber{background:var(--amber-soft)}.b-red{background:var(--red-soft)}.b-paper{background:var(--paper)}
.o-teal{border:2px solid var(--teal)}.o-blue{border:2px solid var(--blue)}.o-amber{border:2px solid var(--amber)}.o-ink{border:2px solid var(--ink)}.o-line{border:2px solid var(--line)}.o-red{border:2px solid var(--red)}
.dash{border-style:dashed!important}
.t-teal{color:var(--teal-ink)}.t-blue{color:var(--blue-ink)}.t-amber{color:var(--amber-ink)}.t-red{color:var(--red)}.t-muted{color:var(--muted)}.t-ink{color:var(--ink)}
.c-teal{--c:var(--teal)}.c-blue{--c:var(--blue)}.c-amber{--c:var(--amber)}.c-red{--c:var(--red)}.c-ink{--c:var(--ink)}.c-grey{--c:var(--faint)}.c-line{--c:var(--line)}
.research .hbars .ttl{color:var(--ink)}.research .hbar .lab{color:var(--muted);opacity:1}.research .hbar .val{color:var(--ink);font-family:var(--f-mono)}.research .hbars .axis{color:var(--muted);opacity:1;font-family:var(--f-mono)}.research .hbars .ax{border-top-color:var(--faint)}
.research .ttl .badge{width:24px;height:24px;font-size:14px}
/* slot grid: several interchangeable parts inside one node (architecture pattern) */
.research .slots{margin-top:10px;width:100%;padding:8px;border:1.5px solid var(--teal);border-radius:10px;background:var(--paper)}
.research .slots-h{margin-bottom:7px;text-align:center;font:600 14px/1 var(--f-mono);color:var(--teal-ink)}
.research .slots-g{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.research .slot{display:flex;flex-direction:column;align-items:center;padding:5px 2px;border-radius:7px;border:1.5px solid var(--amber);background:var(--amber-soft);font:600 14px/1.15 var(--f-body);color:var(--amber-ink)}
.research .slot i{font:400 14px/1.2 var(--f-body);font-style:normal;color:var(--muted)}
.research .slot.dsh{border-style:dashed;background:var(--paper)}
.research .slots-c{margin-top:6px;font-size:14px;line-height:1.25;color:var(--muted)}

motionJs:
