.motion{position:relative;--m-hl:#E1970F;--m-hl-soft:#FDF1DA;--m-on:#0D8682;--m-on-soft:#E1F2F0;--m-on-ink:#075E5B;--m-wire:#8D99AB;--m-paper:#fff}
