/* builds */
.mo-js .motion .f{transition:opacity .45s ease,transform .45s ease,clip-path .7s ease}
.mo-js .motion .f:not(.in){opacity:0}
.mo-js .motion .f.up:not(.in){transform:translateY(14px)}
.mo-js .motion .f.drop:not(.in){transform:translateY(-22px)}
.mo-js .motion .f.zoom:not(.in){transform:scale(.9)}
/* Wipes keep a 24px margin so glow rings and arrowheads outside the box are not clipped. */
.mo-js .motion .f.wr,.mo-js .motion .f.wd,.mo-js .motion .f.wu{clip-path:inset(-24px -24px -24px -24px)}
.mo-js .motion .f.wr:not(.in){opacity:1;clip-path:inset(-24px 100% -24px -24px)}
.mo-js .motion .f.wd:not(.in){opacity:1;clip-path:inset(-24px -24px 100% -24px)}
.mo-js .motion .f.wu:not(.in){opacity:1;clip-path:inset(100% -24px -24px -24px)}
.mo-js .motion .dim{transition:opacity .45s ease}
.mo-js .motion .dim:not(.in){opacity:.28}
.motion .fo{opacity:0}
.mo-js .motion .fo{transition:opacity .6s ease}
.mo-js .motion .fo:not(.in){opacity:1}
.motion .glow{transition:box-shadow .4s ease,background .4s ease,border-color .4s ease}
:root:not(.mo-js) .motion .glow,.motion .glow.in{box-shadow:0 0 0 4px var(--m-hl-soft),0 0 0 6px var(--m-hl)}
.motion .lit{transition:background .35s ease,border-color .35s ease,color .35s ease}
:root:not(.mo-js) .motion .lit,.motion .lit.in{background:var(--m-on-soft);border-color:var(--m-on);color:var(--m-on-ink)}
